# Code generated by Claude
"""
How much of the eagle camera image the hotplate top and the beaker cover at the HANDOFF pose, for the original
level eagle camera and for downward tilts; saves the eagle frames.

    source .venv/bin/activate
    python experiments/beaker_hotplate_eagle_views.py --tag new_pose [--tilts 15 20 25 30 35]

The HANDOFF pose is set directly (no sequence yet): base at the staging pose from src/task_config.py, pedestal at
pedestal_q, the chosen arm at ready_q with the gripper open, then mj_forward. Coverage is the share of pixels
whose first-hit geom is the hotplate top plate (or the beaker), from a 160 x 120 ray grid through the camera, so
occlusion by the bench edge and the arms is included. "level" is the original placeholder (looks along the torso's
+x). Cameras are added as extra cameras so one model serves all variants. Frames go to
data/beaker_hotplate_eagle/<tag>_<camera>.png (the three robot_specs cameras plus the variants).
"""

import argparse
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

if not os.environ.get("DISPLAY") and not os.environ.get("MUJOCO_GL"):
    os.environ["MUJOCO_GL"] = "egl"          # headless shell

import cv2  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.cameras import CameraRig  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402
from src.task_beaker_hotplate import load_task, spawn_and_settle, arm_ids, yaw_to_quat  # noqa: E402

OUT_DIR = PROJECT_ROOT / "data" / "beaker_hotplate_eagle"
LEVEL_LOOK_AT = [1.0, 0.0, 0.45]             # the original eagle placeholder (before the tilt)


def tilted(spec, deg, name):
    s = dict(spec)
    s["name"] = name
    p = np.array(spec["pos"])
    r = math.radians(deg)
    s["look_at"] = (p + np.array([math.cos(r), 0.0, -math.sin(r)])).tolist()
    return s


def coverage(model, data, cam_name, nx=160, ny=120):
    cam = model.camera(cam_name)
    spec = next(c for c in all_specs if c["name"] == cam_name)
    pos, R = data.cam_xpos[cam.id].copy(), data.cam_xmat[cam.id].reshape(3, 3)
    th = math.tan(math.radians(spec["fovy"]) / 2)
    aspect = spec["resolution"][0] / spec["resolution"][1]
    u, v = np.meshgrid(np.linspace(-1, 1, nx), np.linspace(-1, 1, ny))
    d_c = np.c_[(u * th * aspect).ravel(), (v * th).ravel(), -np.ones(nx * ny)]
    dirs = (R @ (d_c / np.linalg.norm(d_c, axis=1, keepdims=True)).T).T
    gid, dist = np.zeros(nx * ny, dtype=np.int32), np.zeros(nx * ny)
    mujoco.mj_multiRay(model, data, pos, dirs.ravel(), None, 1, -1, gid, dist, None, nx * ny, 1e10)
    out = {}
    for k, g in (("hotplate_top", "task_hotplate_top_plate"), ("beaker", "task_beaker_glass")):
        mask = (gid == model.geom(g).id).reshape(ny, nx)
        out[k] = 100.0 * float(mask.mean())
        if mask.any():
            ys, xs = np.nonzero(mask)
            out[k + "_bbox"] = (int(xs.min() * 640 / nx), int(ys.min() * 480 / ny), int(xs.max() * 640 / nx), int(ys.max() * 480 / ny))
        else:
            out[k + "_bbox"] = None
    return out


all_specs = []


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--tag", required=True)
    ap.add_argument("--tilts", type=float, nargs="*", default=[])
    ap.add_argument("--no-frames", action="store_true")
    ap.add_argument("--result", help="staging_result.json from the search, to use instead of the pose in task_config")
    args = ap.parse_args()
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    if args.result:                                  # an alternative staging result instead of the one in the config
        import json
        r = json.loads(Path(args.result).read_text())
        TASK_CFG.update(staging_xy=tuple(r["staging_xy"]), pedestal_q=r["pedestal_q"], arm=r["arm"], ready_q=tuple(r["ready_q"]))

    eagle = next(c for c in robot_specs.CAMERA_SPECS if c["name"] == "eagle_cam")
    level = dict(eagle, name="eagle_level", look_at=LEVEL_LOOK_AT)
    all_specs.extend(robot_specs.CAMERA_SPECS + [level] + [tilted(eagle, t, f"eagle_tilt{t:g}") for t in args.tilts])
    sim = load_task(cameras=all_specs)
    model, data = sim.model, sim.data
    st = spawn_and_settle(sim)
    z_rest = float(data.qpos[2])

    # HANDOFF pose, set directly
    data.qpos[0:7] = [*TASK_CFG["staging_xy"], z_rest, *yaw_to_quat(TASK_CFG["staging_yaw"])]
    for jn in robot_specs.PEDESTAL_SPECS["joints"]:
        data.qpos[model.joint(jn).qposadr[0]] = TASK_CFG["pedestal_q"]
    ids = arm_ids(model, TASK_CFG["arm"])
    for a, q in zip(ids["qadr"], TASK_CFG["ready_q"]):
        data.qpos[a] = q
    for a in ids["fingers"]:
        data.qpos[model.jnt_qposadr[model.actuator_trnid[a, 0]]] = 0.044
    mujoco.mj_forward(model, data)

    print(f"HANDOFF pose ({args.tag}): base {TASK_CFG['staging_xy']}, pedestal {TASK_CFG['pedestal_q']}, {TASK_CFG['arm']} arm ready; "
          f"eagle z {data.cam_xpos[model.camera('eagle_cam').id][2]:.3f} m")
    print(f"{'camera':16s} {'hotplate top %':>15s} {'beaker %':>10s}   bboxes (x0,y0,x1,y1 px of 640x480)")
    for c in ["eagle_level", "eagle_cam"] + [f"eagle_tilt{t:g}" for t in args.tilts]:
        r = coverage(model, data, c)
        label = c + (" (robot_specs)" if c == "eagle_cam" else "")
        print(f"{label:16s} {r['hotplate_top']:15.2f} {r['beaker']:10.2f}   top {r['hotplate_top_bbox']}  beaker {r['beaker_bbox']}")

    if not args.no_frames:
        gl = mujoco.GLContext(model.vis.global_.offwidth, model.vis.global_.offheight)
        gl.make_current()
        rig = CameraRig(model, all_specs, mujoco.MjrContext(model, mujoco.mjtFontScale.mjFONTSCALE_150))
        rig.render(data)
        for c in ["eagle_level", "eagle_cam", "right_wrist_cam", "left_wrist_cam"] + [f"eagle_tilt{t:g}" for t in args.tilts]:
            p = OUT_DIR / f"{args.tag}_{c}.png"
            cv2.imwrite(str(p), cv2.cvtColor(rig.images[c], cv2.COLOR_RGB2BGR))
        print(f"frames: {OUT_DIR.relative_to(PROJECT_ROOT)}/{args.tag}_*.png")


if __name__ == "__main__":
    main()
